import { debounce } from 'lodash';

const wait = 1000;
const maxWait = 2000;

const createAutosave = (callback, options) => {
  const { wait: customWait = wait, maxWait: customMaxWait = maxWait } = options;
  return debounce(callback, customWait, { maxWait: customMaxWait });
};

export { createAutosave };

import { createAutosave } from '../src/debounce';

const wait = 800;
const maxWait = 2000;

const simulateAutosave = (filePath, options) => {
  const { wait: customWait = wait, maxWait: customMaxWait = maxWait } = options;
  const autosave = createAutosave(() => {
    console.log(`Autosaving ${filePath}`);
  }, { wait: customWait, maxWait: customMaxWait });

  return autosave;
};

export { simulateAutosave };
